package io.github.diodeme.ji.host;

import io.github.diodeme.ji.session.tree.SessionRepository;
import java.util.List;
import java.util.Optional;

/** Atomic Host Session, command journal, canonical snapshot, and durable delivery port. */
public interface HostStore extends SessionRepository {
    Reservation reserve(String sessionId, String commandId, String payloadHash, String resultRef,
                        long expectedSessionRevision);
    void release(String sessionId, String commandId, String payloadHash, String resultRef);
    Optional<CommandRecord> command(String sessionId, String commandId, String payloadHash);
    Snapshot snapshot(String sessionId);
    List<DurableEvent> replay(String sessionId, long afterEventSeq);

    record Reservation(long acceptedSeq, String resultRef, Status status) {}
    record Commit(long acceptedSeq, long eventSeq, long snapshotRevision, String resultRef) {}
    record CommandRecord(long acceptedSeq, String resultRef, Status status, Optional<Commit> commit) {
        public CommandRecord { commit = commit == null ? Optional.empty() : commit; }
    }
    enum Status { RESERVED, RETRYABLE, COMPLETED }
    record DurableEvent(long eventSeq, long snapshotRevision, String eventType, byte[] payload) {
        public DurableEvent { payload = payload.clone(); }
        @Override public byte[] payload() { return payload.clone(); }
    }
    record Snapshot(long revision, long baseEventSeq, byte[] payload) {
        public Snapshot { payload = payload.clone(); }
        @Override public byte[] payload() { return payload.clone(); }
    }
}

