package io.github.diodeme.ji.host;

import io.github.diodeme.ji.session.tree.SessionRepository;
import io.github.diodeme.ji.session.tree.SessionInputCoordinator;
import java.util.List;
import java.util.Optional;

/** Atomic Host Session, command journal, canonical snapshot, and durable delivery port. */
public interface HostStore extends SessionRepository, SessionInputCoordinator {
    PromptAcceptance acceptPrompt(
            String sessionId, String commandId, String payloadHash, String resultRef,
            long expectedSessionRevision, String clientId, List<String> content, List<String> attachments);
    Optional<ClaimedPrompt> claimNextPrompt(String sessionId);
    void rollbackClaim(String sessionId, ClaimedPrompt claim);
    void release(String sessionId, String commandId, String payloadHash, String resultRef);
    Optional<CommandRecord> command(String sessionId, String commandId, String payloadHash);
    FollowUpQueue queue(String sessionId);
    FollowUpQueue reorderQueue(String sessionId, List<String> itemIds, long expectedQueueRevision);
    FollowUpQueue promote(String sessionId, String itemId, long expectedQueueRevision);
    FollowUpQueue.Removed remove(String sessionId, String itemId, String requestingClientId,
                                 long expectedQueueRevision);
    FollowUpQueue resumeQueue(String sessionId, long expectedQueueRevision);
    Snapshot snapshot(String sessionId);
    List<DurableEvent> replay(String sessionId, long afterEventSeq);
    Optional<Completion> completion(String resultRef);

    record PromptAcceptance(
            long acceptedSeq, String resultRef, long queueRevision, Status status, boolean startRequired) {}
    record ClaimedPrompt(String sessionId, FollowUpQueue.Item item, String payloadHash, String resultRef) {}
    record Commit(long acceptedSeq, long eventSeq, long snapshotRevision, String resultRef) {}
    record CommandRecord(long acceptedSeq, String resultRef, Status status, Optional<Commit> commit) {
        public CommandRecord { commit = commit == null ? Optional.empty() : commit; }
    }
    record Completion(Commit commit, String outcome) {}
    enum Status { QUEUED, RESERVED, INJECTED, RETRYABLE, COMPLETED, CANCELLED }
    record DurableEvent(long eventSeq, long snapshotRevision, String eventType, byte[] payload) {
        public DurableEvent { payload = payload.clone(); }
        @Override public byte[] payload() { return payload.clone(); }
    }
    record Snapshot(long revision, long baseEventSeq, byte[] payload) {
        public Snapshot { payload = payload.clone(); }
        @Override public byte[] payload() { return payload.clone(); }
    }
}
